function initThemeToggle(){const n=document.querySelector("#theme-toggle");n&&(n.addEventListener("click",()=>{document.body.classList.toggle("dark-mode"),localStorage.setItem("manjusha-theme",document.body.classList.contains("dark-mode")?"dark":"light")}),"dark"===localStorage.getItem("manjusha-theme")&&document.body.classList.add("dark-mode"))}function renderStats(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon" aria-hidden="true">${n.icon}</span>\n            <div>\n                <h4>${n.label}</h4>\n                <p>${n.value}</p>\n            </div>\n        </div>\n    `).join(""))}function renderProcess(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="process-step">\n            <div class="step-number">${String(n.step).padStart(2,"0")}</div>\n            <div class="step-content">\n                <h4>${n.title}</h4>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderMotifs(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="motif-card">\n            <h4>${n.name}</h4>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderStories(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="story-card">\n            <div class="story-icon" aria-hidden="true">${n.icon}</div>\n            <h3>${n.title}</h3>\n            <p>${n.story}</p>\n        </div>\n    `).join(""))}function renderArtisan(n,e){const t=document.getElementById(e);t&&(t.innerHTML=`\n        <h2>${n.title}</h2>\n        <p>${n.description}</p>\n    `)}function renderGallery(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <figure class="gallery-item">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" onerror="this.closest('.gallery-item').style.display='none';">\n            <figcaption>${n.caption}</figcaption>\n        </figure>\n    `).join(""))}function renderReferences(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">${n.text}</a>\n        </li>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{initThemeToggle(),renderStats(MANJUSHA_INFO.quickStats,"quick-stats"),renderProcess(MATERIALS_AND_METHOD,"process-steps"),renderMotifs(TRADITIONAL_MOTIFS,"motif-grid"),renderStories(MYTH_STORIES,"stories-grid"),renderArtisan(ARTISAN_COMMUNITY,"artisan-community"),renderGallery(GALLERY_IMAGES,"gallery-grid"),renderReferences(REFERENCES,"references")});